/// <summary>
/// MPJ_5904_ALMSupplierVolumetricRebates
/// Form handler  for <c>CustFreeInvoice</c> form
/// </summary>
class METCustFreeInvoiceFormHandler
{
}

Method.Source:
   /// <summary>
   /// MPJ_5904_ALMSupplierVolumetricRebates
   /// </summary>
   /// <param name="sender">CustInvoiceTable datasource</param>
   /// <param name="e"><c>CustFreeInvoice</c> form arguments</param>
   [FormDataSourceEventHandler(formDataSourceStr(CustFreeInvoice, CustInvoiceTable), FormDataSourceEventType::Initialized),
       SuppressBPWarning('BPParameterNotUsed', 'Standard parameter required for event interface')]
   public static void CustInvoiceTable_OnInitialized(FormDataSource sender, FormDataSourceEventArgs e)
   {
       FormRun                 custInvoiceForm         = sender.formRun();

       if(custInvoiceForm.args().dataset() == tableNum(METALMSupplierVolumetricRebateHeader))
       {
           METALMSupplierVolumetricRebateHeader rebateHeader = custInvoiceForm.args().record();
           if (rebateHeader)
           {
               sender.query().dataSourceTable(tableNum(CustInvoiceTable)).addRange(fieldNum(CustInvoiceTable, CustomerRef)).value(rebateHeader.InvoiceId);
           }
       }
   }
